window.SPINE_GLOSSARY={version:"2026-10-23a",terms:[{"k":"aal","t":"Annual average loss (AAL)","c":"Catastrophe modelling","s":"The expected loss in a year, averaged across the whole distribution. The primary pricing reference from a cat model.","a":["annual average loss","AAL","average annual loss"]},{"k":"aep","t":"AEP","c":"Catastrophe modelling","s":"Aggregate exceedance probability — the EP curve built from the total of all events in each simulated year.","a":["AEP","aggregate exceedance probability"]},{"k":"aggregate-loss","t":"Aggregate loss","c":"Frequency & severity","s":"Total loss S over a period; in the collective risk model S = ΣX with random frequency N, so E[S] = E[N]·E[X].","a":["aggregate loss","collective risk model"]},{"k":"aleatory","t":"Aleatory uncertainty","c":"Catastrophe modelling","s":"The irreducible randomness of the physical world — which events occur and at what intensity.","a":["aleatory uncertainty","aleatory"]},{"k":"annual-cohort","t":"Annual cohort","c":"IFRS 17 & financial reporting","s":"The rule that no group of contracts may span issue dates more than 12 months apart, keeping profitability trends visible over time.","a":["annual cohort","annual cohorts"]},{"k":"base-cost-of-capital","t":"Base cost of capital","c":"Economics of insurance","s":"The market return shareholders could earn investing the same money themselves — a benchmark, not a source of value.","a":["base cost of capital"]},{"k":"binder","t":"Binding authority (binder)","c":"Products & structures","s":"The delegated agreement letting an MGA bind cover on a carrier's paper within set rules and limits.","a":["binder","binding authority","delegated authority"]},{"k":"bordereaux","t":"Bordereaux","c":"Products & structures","s":"The periodic data returns (premiums, risks, claims) an MGA sends its carrier under the binder.","a":["bordereaux","bordereau"]},{"k":"bornhuetter-ferguson","t":"Bornhuetter-Ferguson","c":"Reserving","s":"Blends chain-ladder with an a-priori expected ultimate for stability on immature years.","a":["Bornhuetter-Ferguson","Bornhuetter Ferguson","BF method"]},{"k":"bottomry","t":"Bottomry","c":"History","s":"Ancient marine loans where extra interest priced the risk of loss — the earliest explicit price of risk.","a":["bottomry","respondentia"]},{"k":"buhlmann-straub","t":"Bühlmann–Straub credibility","c":"Methods & data","s":"A greatest-accuracy credibility method that weights exposures of unequal size — ideal for blending a prior with emerging data.","a":["Bühlmann–Straub","Buhlmann-Straub","Bühlmann","Buhlmann"]},{"k":"capm","t":"CAPM","c":"Methods & data","s":"Capital Asset Pricing Model: only systematic (non-diversifiable) risk earns a return; price = risk-free + beta × equity risk premium.","a":["CAPM","Capital Asset Pricing Model"]},{"k":"cat-bond","t":"Catastrophe bond","c":"Reinsurance & capital","s":"Capital-markets risk transfer: investors take catastrophe risk for a spread; the multiple is spread ÷ expected loss.","a":["cat bond","cat-bond","catastrophe bond"]},{"k":"cat-model","t":"Catastrophe model","c":"Catastrophe modelling","s":"Software that estimates a portfolio’s loss distribution from catastrophes, built from four components run in sequence.","a":["catastrophe model","cat model","cat modelling"]},{"k":"cdf","t":"Cumulative distribution function (CDF)","c":"Statistical foundations","s":"The probability of landing at or below a value — it climbs from 0 to 1.","a":["CDF","cumulative distribution function"]},{"k":"central-limit-theorem","t":"Central limit theorem (CLT)","c":"Statistical foundations","s":"Sums and averages of many independent risks tend to a Normal, whatever their individual shapes.","a":["central limit theorem","CLT"]},{"k":"chain-ladder","t":"Chain-ladder","c":"Reserving","s":"Projects a run-off triangle to ultimate using volume-weighted development factors.","a":["chain-ladder","chain ladder"]},{"k":"cmr","t":"Catastrophe Model Return (CMR)","c":"Catastrophe modelling","s":"The Lloyd’s submission of modelled catastrophe losses at prescribed return periods and perils, using approved vendor models.","a":["catastrophe model return"],"x":0},{"k":"coefficient-of-variation","t":"Coefficient of variation (CV)","c":"Statistical foundations","s":"Standard deviation ÷ mean — relative spread, unitless. Higher CV means a heavier tail.","a":["coefficient of variation","CV"]},{"k":"combined-ratio","t":"Combined ratio","c":"Ratios & KPIs","s":"Loss ratio + expense ratio. Below 100% is an underwriting profit; above 100% an underwriting loss.","a":["combined ratio"]},{"k":"contract-boundary","t":"Contract boundary","c":"IFRS 17 & financial reporting","s":"The line separating cash flows inside a recognised contract from those belonging to a future contract — set where you can reprice to fully reflect risk.","a":["contract boundary","contract boundaries"]},{"k":"cope","t":"COPE","c":"Catastrophe modelling","s":"Construction, Occupancy, Protection, Exposure — the four building-attribute categories that decide which damage function applies.","a":["COPE"]},{"k":"cost-of-equity","t":"Cost of equity","c":"Economics of insurance","s":"The return equity investors require to hold the stock — the hurdle rate ROE is judged against.","a":["cost of equity","cost of capital","Ke"]},{"k":"coverage-units","t":"Coverage units","c":"IFRS 17 & financial reporting","s":"The measure of service provided each period (duration × size of cover) that drives how the CSM releases to revenue.","a":["coverage units","coverage unit"]},{"k":"credibility","t":"Credibility","c":"Methods & data","s":"How much weight a risk's own experience gets vs the book/market: Rate = Z·own + (1−Z)·prior.","a":["credibility","credibility theory"]},{"k":"csm","t":"Contractual Service Margin (CSM)","c":"IFRS 17 & financial reporting","s":"The store of unearned profit on a group of contracts, released to revenue as coverage is provided; it cannot be negative.","a":["Contractual Service Margin","CSM"]},{"k":"dac","t":"Deferred acquisition costs (DAC)","c":"Reserving","s":"Commission and other acquisition costs carried forward and expensed as premium earns. Under IFRS 17 the unamortised balance sits inside the LRC rather than being a separate asset.","a":["deferred acquisition costs","DAC"]},{"k":"damage-function","t":"Damage function","c":"Catastrophe modelling","s":"The curve mapping hazard intensity to expected damage ratio for one building type.","a":["damage function","damage curve","depth-damage"]},{"k":"damage-ratio","t":"Damage ratio","c":"Catastrophe modelling","s":"The proportion of total insured value expected to be destroyed at a given intensity. The vulnerability module’s output.","a":["damage ratio","mean damage ratio"]},{"k":"deductible","t":"Deductible / excess","c":"Rating & premium","s":"The amount of a loss the policyholder retains before cover responds.","a":["deductible","policy excess"]},{"k":"demand-surge","t":"Demand surge","c":"Catastrophe modelling","s":"Post-event inflation of repair costs, driven by simultaneous excess demand for labour and materials across a whole affected region.","a":["demand surge","loss amplification"]},{"k":"deposit-replacement","t":"Deposit replacement","c":"Products & structures","s":"A tenant pays a fee instead of a cash deposit; the guarantee pays the landlord for damage/arrears and pursues the tenant.","a":["deposit replacement","deposit guarantee","deposit-replacement"]},{"k":"development-factor","t":"Development factor","c":"Reserving","s":"The ratio linking successive columns of a loss triangle; chained together they project to ultimate.","a":["development factor","development factors","age-to-age factor"]},{"k":"discounting","t":"Discounting of insurance liabilities","c":"IFRS 17 & financial reporting","s":"Holding claims reserves at present value rather than at the undiscounted amount — the single largest measurement change IFRS 17 brought to general insurance.","a":["discounting","discounted claims reserves","time value of money"]},{"k":"ebitda","t":"EBITDA","c":"Ratios & KPIs","s":"Earnings before interest, tax, depreciation and amortisation — the cross-sector comparability metric. IFRS 17 shares its goal and reverses its method.","a":["EBITDA"]},{"k":"economic-net-worth","t":"Economic net worth","c":"Economics of insurance","s":"Market value of assets less the economic value of liabilities — the tangible worth to shareholders.","a":["economic net worth"]},{"k":"economic-value","t":"Economic value","c":"Economics of insurance","s":"Value on a market-consistent basis: assets at market value, liabilities at the replication value plus frictional costs.","a":["economic value","economic value of liabilities"]},{"k":"ep-curve","t":"EP curve","c":"Catastrophe modelling","s":"Exceedance probability curve — every loss level mapped to its annual probability of being exceeded. The primary output of a cat model.","a":["EP curve","exceedance probability curve"]},{"k":"epistemic","t":"Epistemic uncertainty","c":"Catastrophe modelling","s":"Uncertainty from incomplete scientific knowledge — things the model could in principle know better.","a":["epistemic uncertainty","epistemic"]},{"k":"excess-of-loss","t":"Excess-of-loss (XoL)","c":"Reinsurance & capital","s":"Non-proportional reinsurance covering the slice of loss between an attachment and a limit — caps large losses.","a":["excess-of-loss","excess of loss","XoL","XOL"]},{"k":"expected-value","t":"Expected value (mean)","c":"Statistical foundations","s":"The probability-weighted average outcome — where the distribution balances.","a":["expected value","mean","E[X]"]},{"k":"expense-ratio","t":"Expense ratio","c":"Ratios & KPIs","s":"Operating expenses (acquisition + management) as a percentage of premium.","a":["expense ratio"]},{"k":"experience-rating","t":"Experience rating","c":"Methods & data","s":"Pricing from the risk's own historical claims (burning cost) — useless with no data, powerful once a triangle exists.","a":["experience rating","experience-rated","burning cost"]},{"k":"exponential-distribution","t":"Exponential distribution","c":"Statistical foundations","s":"The memoryless waiting-time distribution; a Gamma with shape 1.","a":["exponential distribution","exponential"]},{"k":"exposure","t":"Exposure","c":"Rating & premium","s":"The measure of how much risk is present (vehicle-years, £m revenue, sum insured) that premium scales on.","a":["exposure base","exposure"]},{"k":"exposure-curve","t":"Exposure curve","c":"Methods & data","s":"Industry-derived curves (Swiss Re / MBBEFD, Riebesell) that encode how loss is distributed by size — external severity data.","a":["exposure curve","exposure curves","MBBEFD","Riebesell","increased limit factor","increased-limit factors"]},{"k":"exposure-rating","t":"Exposure rating","c":"Methods & data","s":"Pricing from the current risk's structure and external severity curves rather than its own past claims.","a":["exposure rating","exposure-rated"]},{"k":"fair-value","t":"Fair value (Consumer Duty / PROD)","c":"Regulation & governance","s":"The FCA requirement that price is reasonable relative to benefits — tested via claims ratio vs commission, especially for add-ons.","a":["fair value","fair value assessment","Consumer Duty","PROD 4","PROD"]},{"k":"financial-module","t":"Financial module","c":"Catastrophe modelling","s":"The cat model component that applies policy conditions, turning ground-up loss into insured loss.","a":["financial module"]},{"k":"footprint","t":"Hazard footprint","c":"Catastrophe modelling","s":"The geographic spread of intensity from a single catalogue event — a hurricane’s wind field, an earthquake’s ground motion pattern, a flood’s inundation extent.","a":["hazard footprint","footprint"]},{"k":"franchise-value","t":"Franchise value","c":"Economics of insurance","s":"The premium over economic net worth — the present value of profits from future business.","a":["franchise value"]},{"k":"frequency","t":"Frequency","c":"Frequency & severity","s":"The number of claims N a risk generates in a period; modelled with Poisson or negative binomial.","a":["frequency","claim frequency"]},{"k":"frictional-capital","t":"Frictional capital cost","c":"Economics of insurance","s":"The insurer-specific cost of holding risk capital: double taxation, financial distress, agency and regulatory costs.","a":["frictional capital","frictional capital costs","frictional cost"]},{"k":"frs-103","t":"FRS 103 (UK GAAP insurance)","c":"IFRS 17 & financial reporting","s":"The UK GAAP standard for insurance contracts: statutory reserves, GI usually undiscounted, no explicit risk adjustment or CSM.","a":["FRS 103","FRS103"]},{"k":"fulfilment-cash-flows","t":"Fulfilment cash flows (FCF)","c":"IFRS 17 & financial reporting","s":"The current, explicit cost of meeting a contract: probability-weighted future cash flows + discounting + a risk adjustment.","a":["fulfilment cash flows","fulfillment cash flows","FCF"]},{"k":"gamma","t":"Gamma distribution","c":"Frequency & severity","s":"A positive, moderately skewed distribution used for claim severity, including on the severity side of a GLM.","a":["Gamma distribution","Gamma"]},{"k":"geocoding","t":"Geocoding","c":"Catastrophe modelling","s":"Converting an address into coordinates so a location can be placed on the hazard grid.","a":["geocoding","geocode","country centroid"]},{"k":"glm","t":"Generalised linear model (GLM)","c":"Rating & premium","s":"The workhorse rating model: a log link makes the linear predictor additive, so the rate is multiplicative (base × relativities).","a":["GLM","generalised linear model","generalized linear model"]},{"k":"gmm","t":"General Measurement Model (GMM / BBA)","c":"IFRS 17 & financial reporting","s":"The default IFRS 17 model: liability = fulfilment cash flows + CSM, with the CSM unlocked for future service and released over coverage units.","a":["General Measurement Model","GMM","building block approach","BBA"]},{"k":"grossing-up","t":"Grossing-up","c":"Rating & premium","s":"Turning cost into price by dividing by (1 − variable% − profit%), because variable loads are charged on the final premium.","a":["grossing-up","gross-up","grossing up"]},{"k":"ground-up-loss","t":"Ground-up loss","c":"Catastrophe modelling","s":"Total physical damage before any policy terms. Gross loss is after primary policy conditions; net loss is after reinsurance recoveries.","a":["ground-up loss","ground up loss","gross loss","net loss"]},{"k":"gwp","t":"Gross written premium (GWP)","c":"Ratios & KPIs","s":"Premium contracted in the period, before reinsurance and before earning. No longer an IFRS 17 measure — it survives only as an alternative performance measure.","a":["gross written premium","GWP","gross premiums written"]},{"k":"hazard-module","t":"Hazard module","c":"Catastrophe modelling","s":"The first cat model component: takes a coordinate and returns the distribution of physical intensities possible there.","a":["hazard module"]},{"k":"ibnr","t":"IBNR","c":"Reserving","s":"Incurred But Not Reported: reserves held for claims that have happened but aren't yet fully reported or settled.","a":["IBNR","incurred but not reported"]},{"k":"icwp","t":"Insurance contract written premium (ICWP)","c":"Ratios & KPIs","s":"The alternative performance measure insurers publish in place of gross written premium under IFRS 17.","a":["insurance contract written premium","ICWP","insurance written premiums"]},{"k":"ifie","t":"Insurance finance income/expenses (IFIE)","c":"IFRS 17 & financial reporting","s":"The effect of the time value of money and financial risk on insurance liabilities — the discount unwind plus rate-change effects.","a":["insurance finance income","insurance finance expenses","insurance finance income/expenses","IFIE"]},{"k":"ifrs-17","t":"IFRS 17","c":"IFRS 17 & financial reporting","s":"The accounting standard for insurance contracts (effective 1 Jan 2023) that measures every contract at current value and defers unearned profit into the CSM.","a":["IFRS 17","IFRS17"]},{"k":"insurance-revenue","t":"Insurance revenue","c":"IFRS 17 & financial reporting","s":"The IFRS 17 top line — earned coverage recognised as service is provided, excluding investment components. It replaces gross written premium.","a":["insurance revenue"]},{"k":"insurance-service-result","t":"Insurance service result","c":"IFRS 17 & financial reporting","s":"Insurance revenue less insurance service expenses — the IFRS 17 underwriting result, and the true measure to reconcile any combined ratio to.","a":["insurance service result"]},{"k":"intensity-metric","t":"Intensity metric","c":"Catastrophe modelling","s":"The physical quantity the hazard module reports, chosen per peril because it is what drives damage.","a":["intensity metric"]},{"k":"law-of-large-numbers","t":"Law of large numbers","c":"History","s":"Bernoulli's result (1713) that pooling enough independent risks makes the average outcome predictable.","a":["law of large numbers"]},{"k":"legal-indemnity","t":"Legal indemnity / title insurance","c":"Products & structures","s":"Single-premium, perpetuity cover for a pre-identified title or conveyancing defect so a property sale can complete.","a":["legal indemnity","title insurance","contingent legal-risk","contingent legal risk"]},{"k":"lic","t":"Liability for incurred claims (LIC)","c":"IFRS 17 & financial reporting","s":"The liability for claims already incurred — always full fulfilment cash flows: discounted best estimate + risk adjustment.","a":["liability for incurred claims","LIC"]},{"k":"lognormal","t":"Lognormal distribution","c":"Frequency & severity","s":"A heavy-tailed severity/aggregate distribution; its stop-loss transform has a clean closed form.","a":["lognormal","log-normal"]},{"k":"loss-component","t":"Loss component","c":"IFRS 17 & financial reporting","s":"The tracked balance for an onerous group's expected loss, recognised in P&L immediately and kept out of future insurance revenue.","a":["loss component","onerous contract","onerous contracts","onerous"]},{"k":"loss-ratio","t":"Loss ratio","c":"Ratios & KPIs","s":"Incurred claims as a percentage of earned premium — the core measure of underwriting performance.","a":["loss ratio","loss ratios"]},{"k":"loss-recovery-component","t":"Loss-recovery component","c":"IFRS 17 & financial reporting","s":"The up-front gain recognised on reinsurance held when the underlying contracts are onerous — the one place the deferral asymmetry is restored.","a":["loss-recovery component","loss recovery component"]},{"k":"losses-occurring","t":"Losses-occurring basis","c":"Reinsurance & capital","s":"A treaty covering losses that happen during the treaty year, whenever the underlying policy was written — so the coverage period is the treaty term.","a":["losses-occurring","losses occurring","loss-occurring","losses occurring during"]},{"k":"lrc","t":"Liability for remaining coverage (LRC)","c":"IFRS 17 & financial reporting","s":"The liability for cover not yet provided — under PAA, essentially the unearned premium reserve.","a":["liability for remaining coverage","LRC"]},{"k":"method-of-moments","t":"Method of moments","c":"Statistical foundations","s":"Fitting by matching the model's mean and variance to the sample's — quick, if slightly less efficient than MLE.","a":["method of moments"]},{"k":"mga","t":"Managing general agent (MGA)","c":"Products & structures","s":"An intermediary with delegated authority to underwrite and bind on an insurer's paper.","a":["MGA","managing general agent"]},{"k":"mle","t":"Maximum likelihood estimation (MLE)","c":"Statistical foundations","s":"Choosing the parameters that make the observed data most likely — the standard way to fit a distribution.","a":["maximum likelihood","MLE","maximum-likelihood"]},{"k":"monte-carlo","t":"Monte-Carlo simulation","c":"Methods & data","s":"Drawing many random futures and reading the distribution of outcomes off the sample.","a":["Monte-Carlo","Monte Carlo","simulation"]},{"k":"negative-binomial","t":"Negative binomial","c":"Statistical foundations","s":"A frequency model for over-dispersed counts — a Poisson whose rate λ is itself random.","a":["negative binomial"]},{"k":"nested-stochastic","t":"Nested stochastic projection","c":"Methods & data","s":"A real-world outer simulation where each path needs a risk-neutral inner valuation — very compute-heavy.","a":["nested stochastic","nested-stochastic","stochastic-on-stochastic"]},{"k":"non-modelled-items","t":"Non-modelled items","c":"Catastrophe modelling","s":"Perils, geographies or coverage types a model does not attempt to represent — and reports as zero rather than as unknown.","a":["non-modelled items","non-modelled","non-modeled"]},{"k":"normal","t":"Normal (Gaussian) distribution","c":"Statistical foundations","s":"The symmetric bell curve set by a mean and standard deviation; averages of many risks tend to it.","a":["Normal distribution","Gaussian","normal distribution"]},{"k":"oci-option","t":"OCI option","c":"IFRS 17 & financial reporting","s":"The accounting-policy choice to route discount-rate movements on liabilities through OCI rather than P&L, damping earnings volatility.","a":["OCI option"]},{"k":"oep","t":"OEP","c":"Catastrophe modelling","s":"Occurrence exceedance probability — the EP curve built from the single largest event in each simulated year.","a":["OEP","occurrence exceedance probability"]},{"k":"onerous","t":"Onerous contract","c":"IFRS 17 & financial reporting","s":"A group of contracts expected to lose money over its coverage period. IFRS 17 requires the loss to be recognised immediately as a loss component.","a":["onerous contract","onerous","onerous cohort"]},{"k":"over-dispersion","t":"Over-dispersion","c":"Statistical foundations","s":"Variance greater than the mean in count data — the sign a plain Poisson is too tight.","a":["over-dispersion","overdispersion"]},{"k":"paa","t":"Premium Allocation Approach (PAA)","c":"IFRS 17 & financial reporting","s":"The GI-friendly simplification where the LRC behaves like the unearned premium reserve; the LIC is still full fulfilment cash flows.","a":["Premium Allocation Approach","PAA"]},{"k":"parameter-risk","t":"Parameter (estimation) risk","c":"Methods & data","s":"The risk that your estimated mean is simply wrong — dominant when you have little or no data.","a":["parameter risk","parameter uncertainty","estimation risk","parameter/estimation risk"]},{"k":"payback","t":"Payback period","c":"Reinsurance & capital","s":"The reciprocal of rate-on-line: how many years of premium equal the layer limit.","a":["payback"]},{"k":"pb-multiple","t":"Price-to-book (P/B) multiple","c":"Economics of insurance","s":"Market capitalisation divided by book value; reflects whether the business earns above or below its cost of equity.","a":["P/B multiple","P/B","price-to-book","price to book"]},{"k":"pdf","t":"Probability density function (PDF)","c":"Statistical foundations","s":"For a continuous amount, the curve whose area between two points is the probability of landing there.","a":["PDF","probability density function","density"]},{"k":"pmf","t":"Probability mass function (PMF)","c":"Statistical foundations","s":"For a count variable, the probability of each exact value — e.g. P(exactly 2 claims).","a":["PMF","probability mass function"]},{"k":"pml","t":"Probable maximum loss (PML)","c":"Catastrophe modelling","s":"The largest loss a portfolio is likely to sustain from a single catastrophe event. A risk-management concept rather than a single defined statistic.","a":["probable maximum loss","PML","maximum foreseeable loss","MFL"]},{"k":"poisson","t":"Poisson distribution","c":"Frequency & severity","s":"The canonical count distribution for claim frequency, with equal mean and variance.","a":["Poisson"]},{"k":"policy-limit","t":"Policy limit","c":"Rating & premium","s":"The maximum the insurer will pay; caps severity and drives increased-limit pricing.","a":["policy limit","limit of indemnity","limit"]},{"k":"probability-distribution","t":"Probability distribution","c":"Statistical foundations","s":"A rule spreading 100% of probability across possible outcomes; height is density, area is probability.","a":["probability distribution","distribution"]},{"k":"protection-gap","t":"Protection gap","c":"Catastrophe modelling","s":"The difference between total economic loss from a catastrophe and the insured loss the industry pays.","a":["protection gap"]},{"k":"pure-premium","t":"Pure premium","c":"Rating & premium","s":"The expected cost of claims — E[Loss] — the first rung of the technical-price ladder.","a":["pure premium","risk premium","loss cost"]},{"k":"quota-share","t":"Quota share","c":"Reinsurance & capital","s":"Proportional reinsurance that cedes a fixed percentage of every risk — sharing premium, losses and capital from the ground up.","a":["quota share","quota-share","QS"]},{"k":"rate-adequacy","t":"Rate adequacy","c":"Rating & premium","s":"Charged premium ÷ technical premium — how close the price is to the risk-adequate level.","a":["rate adequacy"]},{"k":"rate-on-line","t":"Rate-on-line","c":"Reinsurance & capital","s":"Layer premium ÷ limit; its reciprocal is the payback period.","a":["rate-on-line","rate on line","ROL"]},{"k":"rds","t":"Realistic Disaster Scenario (RDS)","c":"Catastrophe modelling","s":"A suite of specific catastrophe scenarios defined by Lloyd’s that every syndicate must estimate its exposure to.","a":["realistic disaster scenario","RDS","realistic disaster scenarios"]},{"k":"reinstatement-premium","t":"Reinstatement premium","c":"Reinsurance & capital","s":"Paid to restore a limit after a loss. Because it is triggered by the claim, it nets against incurred claims rather than being counted as revenue.","a":["reinstatement premium","reinstatement premiums"]},{"k":"reinsurance","t":"Reinsurance","c":"Reinsurance & capital","s":"Insurance for insurers: transferring part of the risk (and capital need) to another carrier.","a":["reinsurance","reinsurer","reinsurers"]},{"k":"reinsurance-held","t":"Reinsurance contracts held","c":"IFRS 17 & financial reporting","s":"Reinsurance you buy, measured separately from the underlying, with its own CSM for the net cost of cover and no onerous concept.","a":["reinsurance contracts held","reinsurance held"]},{"k":"reinsurance-issued","t":"Reinsurance contracts issued","c":"Reinsurance & capital","s":"Reinsurance written by the reinsurer. Measured as ordinary insurance issued — the IFRS 17 asymmetries belong to contracts held, not issued.","a":["reinsurance contracts issued","reinsurance issued","inwards reinsurance","assumed reinsurance"]},{"k":"relativity","t":"Relativity","c":"Rating & premium","s":"A multiplicative rating factor exp(β); the base level is fixed at 1.0.","a":["relativity","relativities","rating factor","rating factors"]},{"k":"replicating-portfolio","t":"Replicating portfolio","c":"Economics of insurance","s":"The traded portfolio that best matches a liability's cash flows; its market value prices the liability by no-arbitrage.","a":["replicating portfolio","hedge portfolio"]},{"k":"reserving","t":"Reserving","c":"Reserving","s":"Estimating the money to set aside for claims already incurred — closed, reported-but-not-settled, and IBNR.","a":["reserving","loss reserving","reserve","reserves"]},{"k":"return-period","t":"Return period","c":"Reinsurance & capital","s":"The average interval between losses of a given size — a 1-in-200 loss is the 99.5% quantile.","a":["return period","return-period","1-in-200","1-in-100"]},{"k":"risk-adjustment","t":"Risk adjustment for non-financial risk","c":"IFRS 17 & financial reporting","s":"The entity-specific compensation an insurer requires for bearing non-financial (insurance/lapse/expense) uncertainty; its confidence level must be disclosed.","a":["risk adjustment","risk adjustment for non-financial risk"]},{"k":"risk-margin","t":"Risk margin","c":"Reinsurance & capital","s":"The loading over the best estimate for bearing uncertainty; larger when data is scarce.","a":["risk margin","safety loading","risk loading"]},{"k":"risks-attaching","t":"Risks-attaching basis","c":"Reinsurance & capital","s":"A treaty covering the underlying policies that incept during the treaty year — so the reinsurer's coverage period runs beyond the treaty term.","a":["risks-attaching","risks attaching","risk-attaching","risk attaching"]},{"k":"roe","t":"Return on equity (ROE)","c":"Ratios & KPIs","s":"Net profit as a percentage of shareholders' equity — the primary shareholder-value metric in insurance.","a":["ROE","return on equity"]},{"k":"ruin-theory","t":"Ruin theory","c":"History","s":"Lundberg's 1903 idea that premiums need a safety loading so the probability of exhausting capital stays acceptably small.","a":["ruin theory","probability of ruin","collective risk theory"]},{"k":"run-off-triangle","t":"Run-off triangle","c":"Reserving","s":"A grid of cumulative losses by origin (accident) year and development period — the input to reserving.","a":["run-off triangle","loss triangle","development triangle"]},{"k":"scr","t":"Solvency Capital Requirement (SCR)","c":"Reinsurance & capital","s":"The capital an insurer must hold to survive a 1-in-200-year loss (99.5% VaR over one year) under Solvency II.","a":["SCR","Solvency Capital Requirement"]},{"k":"secondary-uncertainty","t":"Secondary uncertainty","c":"Catastrophe modelling","s":"The spread of possible damage once the event intensity is already known.","a":["secondary uncertainty","primary uncertainty"]},{"k":"severity","t":"Severity","c":"Frequency & severity","s":"The size X of an individual claim; modelled with skewed, heavy-tailed distributions (Gamma, lognormal, Pareto).","a":["severity","claim severity"]},{"k":"solvency-ii","t":"Solvency II","c":"Regulation & governance","s":"The EU risk-based capital regime (in force 2016); market-consistent balance sheet, SCR at 99.5% VaR, explicit risk margin.","a":["Solvency II","Solvency 2"]},{"k":"sov","t":"Schedule of values (SOV)","c":"Catastrophe modelling","s":"The structured list of insured locations submitted with a risk — one row per location, with address, value and building attributes.","a":["schedule of values","SOV"]},{"k":"standard-deviation","t":"Standard deviation","c":"Statistical foundations","s":"The square root of the variance — typical distance of an outcome from the mean, in the data's own units.","a":["standard deviation","std dev"]},{"k":"stochastic-catalogue","t":"Stochastic event catalogue","c":"Catastrophe modelling","s":"A synthetic database of simulated events, each with an assigned annual rate. The core of the hazard module.","a":["stochastic event catalogue","stochastic catalogue","event catalogue"]},{"k":"stop-loss","t":"Stop-loss","c":"Frequency & severity","s":"The expected loss above a retention, E[(L−d)⁺] — the building block of layer and aggregate pricing.","a":["stop-loss","stop loss","stop-loss transform"]},{"k":"surety","t":"Surety / guarantee","c":"Products & structures","s":"A three-party promise to pay a beneficiary if the principal defaults, with a right to recover from the principal.","a":["surety","guarantee bond"]},{"k":"target-market","t":"Target market","c":"Regulation & governance","s":"The defined group a product is designed for — a required part of product governance under PROD.","a":["target market"]},{"k":"technical-premium","t":"Technical premium","c":"Rating & premium","s":"The risk-adequate cost: pure premium plus loss loadings, expenses and the cost of capital.","a":["technical premium","technical price"]},{"k":"technical-provisions","t":"Technical provisions (Solvency UK)","c":"IFRS 17 & financial reporting","s":"The Solvency UK value of insurance liabilities: best estimate + a prescribed cost-of-capital risk margin, with no CSM.","a":["technical provisions"]},{"k":"tiv","t":"Total insured value (TIV)","c":"Catastrophe modelling","s":"The value at risk at a single location, on a replacement-cost basis. The multiplier in the loss calculation.","a":["total insured value","TIV"]},{"k":"tvar","t":"Tail-VaR (TVaR)","c":"Reinsurance & capital","s":"The expected loss beyond VaR — a coherent risk measure that looks into the tail, not just at its edge.","a":["TVaR","Tail-VaR","tail value at risk","TVaR/CTE"]},{"k":"ultimate","t":"Ultimate loss","c":"Reserving","s":"The final expected cost of a cohort of claims once fully developed and settled.","a":["ultimate loss","ultimate"]},{"k":"underwriting-cycle","t":"Underwriting cycle","c":"Rating & premium","s":"The multi-year oscillation of rates and combined ratios driven by capital flows and competition.","a":["underwriting cycle","hard market","soft market"]},{"k":"upr","t":"Unearned premium reserve (UPR)","c":"Reserving","s":"The part of written premium relating to cover not yet provided. Under IFRS 17 it is subsumed into the liability for remaining coverage.","a":["unearned premium reserve","UPR","unearned premium"]},{"k":"var","t":"Value-at-Risk (VaR)","c":"Reinsurance & capital","s":"The loss at a given quantile (e.g. 99.5%); the SCR is calibrated to a 1-in-200-year VaR.","a":["VaR","Value-at-Risk","value at risk"]},{"k":"variance","t":"Variance","c":"Statistical foundations","s":"The average squared distance from the mean — how much outcomes scatter.","a":["variance"]},{"k":"vfa","t":"Variable Fee Approach (VFA)","c":"IFRS 17 & financial reporting","s":"A GMM variant for direct-participating contracts, where the CSM absorbs the entity's share of underlying-item and financial changes.","a":["Variable Fee Approach","VFA"]},{"k":"view-of-risk","t":"View of risk","c":"Catastrophe modelling","s":"The professional position on a risk: model output plus documented adjustment for what the model does not cover.","a":["view of risk"]},{"k":"vulnerability-module","t":"Vulnerability module","c":"Catastrophe modelling","s":"The cat model component that converts a hazard intensity and a building description into a damage ratio.","a":["vulnerability module"]}]};
